def intersection_area(rect1, rect2):
    # Find the bounding box of the intersection
    left = max(min(x for x, y in rect1), min(x for x, y in rect2))
    right = min(max(x for x, y in rect1), max(x for x, y in rect2))
    bottom = max(min(y for x, y in rect1), min(y for x, y in rect2))
    top = min(max(y for x, y in rect1), max(y for x, y in rect2))

    if left < right and bottom < top:
        return (right - left) * (top - bottom)
    else:
